func LookupEntity(stepName string) (EntityDef, bool) {
	if def, ok := Entities[stepName]; ok {
		return def, true
	}
	return EntityDef{}, false
}

func LookupType(typeName string) (TypeDef, bool) {
	if def, ok := Types[typeName]; ok {
		return def, true
	}
	return TypeDef{}, false
}
